@@ -0,0 +1,82 @@
+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru.ts';
+
+test('a hit refreshes recency', () => {
+  const evicted: unknown[] = [];
+  const cache = new LRU<string, number>(2, 1000, () => 0);
+  cache.onEvict = (...args) => evicted.push(args);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('live boundary and expired get', () => {
+  let t = 0;
+  const evicted: unknown[] = [];
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.onEvict = (...args) => evicted.push(args);
+  cache.set('a', 1);
+  t = 999;
+  expect(cache.get('a')).toBe(1);
+  t = 1000;
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+});
+
+test('set refreshes ttl', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.set('a', 1);
+  t = 500;
+  cache.set('a', 1);
+  t = 1200;
+  expect(cache.get('a')).toBe(1);
+});
+
+test('expired entries are evicted before live ones', () => {
+  let t = 0;
+  const evicted: unknown[] = [];
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.onEvict = (...args) => evicted.push(args);
+  cache.set('a', 1);
+  t = 600;
+  cache.set('b', 2);
+  t = 1100;
+  cache.set('c', 3);
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('delete reports live, expired and missing entries', () => {
+  let t = 0;
+  const evicted: unknown[] = [];
+  const cache = new LRU<string, number>(5, 1000, () => t);
+  cache.onEvict = (...args) => evicted.push(args);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.delete('a')).toBe(true);
+  t = 1000;
+  expect(cache.delete('b')).toBe(false);
+  expect(cache.delete('zz')).toBe(false);
+  expect(evicted).toEqual([
+    ['a', 1, 'delete'],
+    ['b', 2, 'expired'],
+  ]);
+});
+
+test('size and keys skip expired entries without evicting', () => {
+  let t = 0;
+  const evicted: unknown[] = [];
+  const cache = new LRU<string, number>(5, 1000, () => t);
+  cache.onEvict = (...args) => evicted.push(args);
+  cache.set('a', 1);
+  t = 600;
+  cache.set('b', 2);
+  t = 1000;
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+  expect(evicted).toEqual([]);
+});
